if ch == '\n' {
	// detect whether we have the start of a heredoc; only
	// consider it a heredoc if the marker is the entire token
	// on this line, so that other tokens like << and >> (or
	// tokens with spaces on the same line) are lexed normally
	if !heredocEscaped && len(val) > 1 && string(val[:2]) == "<<" {
		marker := string(val[2:])
		if len(marker) > 0 && marker[0] == '<' {
			return false, fmt.Errorf("too many '<' for heredoc on line #%d; only use two, for example <<END", l.line)
		}
		if !heredocMarkerRegexp.MatchString(marker) {
			return false, fmt.Errorf("heredoc marker on line #%d must contain only alpha-numeric characters, dashes and underscores; got '%s'", l.line, marker)
		}

		// the heredoc marker is the characters after the two <<
		// and the newline; reset val because the heredoc is
		// syntax we don't want to keep
		l.marker = marker
		l.inHeredoc = true
		l.skippedLines++
		val = nil
		continue
	}

	// newlines can be escaped to chain arguments
	// onto multiple lines; else, increment the line count
	if escaped {
		l.skippedLines++
		escaped = false
	} else {
		l.line += 1 + l.skippedLines
		l.skippedLines = 0
	}
